// ---------------------------------------------------------------
// Flatten Retell's call_analyzed payload.
//
// Retell nests the Post-Call Data Extraction fields deeply:
//   body.call.call_analysis.custom_analysis_data.claim_filed
// Retyping that path in several nodes is the single most common reason
// a post-call workflow "runs green but does nothing" -- one mistyped
// path yields undefined silently instead of erroring. Resolve it once.
// ---------------------------------------------------------------

const body = $json.body ?? $json;
const call = body.call ?? body;
const analysis = call.call_analysis ?? {};
const data = analysis.custom_analysis_data ?? body.custom_analysis_data ?? {};

const str = (v) => (v === undefined || v === null ? '' : String(v).trim());

// Extraction can return a real boolean or the strings "true"/"false".
// Normalise to a real boolean so the IF node tests one predictable type.
const claimFiled =
  data.claim_filed === true ||
  String(data.claim_filed).toLowerCase() === 'true';

const n = new Date();
const p = (x) => String(x).padStart(2, '0');

return [{ json: {
  call_id: str(call.call_id),
  claim_filed: claimFiled,
  claim_id: str(data.claim_id),
  urgency: str(data.urgency) || 'n/a',
  name: str(data.name),
  email: str(data.email).toLowerCase(),
  incident_type: str(data.incident_type) || 'n/a',
  call_summary: str(analysis.call_summary),
  timestamp: `${n.getFullYear()}-${p(n.getMonth() + 1)}-${p(n.getDate())} ` +
             `${p(n.getHours())}:${p(n.getMinutes())}`
}}];

const f = $('Flatten Retell Payload').first().json;

// $json here is Gmail's API response, not the call data --
// every n8n node replaces $json with its own output.
return [{ json: {
  timestamp: f.timestamp,
  claim_filed: true,
  urgency: f.urgency,
  incident_type: f.incident_type
}}];

const f = $json;

// Logging calls where nothing was filed is what makes the volume
// chart meaningful -- without it you only ever see successes and
// cannot compute a conversion rate.
return [{ json: {
  timestamp: f.timestamp,
  claim_filed: false,
  urgency: 'n/a',
  incident_type: 'n/a'
}}];
